import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { ArticleService } from 'src/app/data/service/article/article.service';
import { IArticleFilterModel, ArticleFilterModel } from '../../../../../data/model/article/ArticleFilterModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';

@Component({
  selector: 'app-liked-articles',
  templateUrl: './liked-articles.component.html',
  styleUrls: ['./liked-articles.component.scss']
})
export class LikedArticlesComponent implements OnInit {

  filteredArticles: IArticleFilterModel;
  selectedArticleId = 0;
  searchTitle = '';
  
  constructor(
    private articleService: ArticleService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    let filter: IArticleFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page ? params.page : 1;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;

      filter = new ArticleFilterModel(page, take, title);

      this.filteredArticles = filter;

      SharedIonic.loading(this.loadingController);

      this.articleService.GetAdminArticlesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredArticles = res.data;
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredArticles.startPage == null) {
      return;
    }
    if (this.filteredArticles.pageId > this.filteredArticles.startPage && +this.filteredArticles.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredArticles.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredArticles.endPage == null) {
      return;
    }
    if (this.filteredArticles.pageId < this.filteredArticles.endPage) {
      this.setQueryParams(+this.filteredArticles.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredArticles.title = this.searchTitle;

    this.router
      .navigate(
        ['AdminPanel', 'LikedArticles'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredArticles.takeEntity ? this.filteredArticles.takeEntity : null,
            title: this.filteredArticles.title ? this.filteredArticles.title : null
          }
        });
  }

  async presentAlertConfirm(like: number, dissLike: number) {

    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'علاقه مندی',
      message: 'راضی: ' + like + ' _ ناراضی: ' + dissLike,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  onSelectItem(id: string | number) {

    this.selectedArticleId = +id;

    let like = 0;
    let dissLike = 0;

    SharedIonic.loading(this.loadingController);

    this.articleService.GetArticleLikeById(this.selectedArticleId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          like = res.data.like;
          dissLike = res.data.dissLike;

          this.presentAlertConfirm(like, dissLike);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }
}
